import React from "react";
import { mocked } from "jest-mock";
import { MatrixClient, Room, RoomMember } from "matrix-js-sdk/src/matrix";
import { act, fireEvent, render, RenderResult, screen } from "@testing-library/react";
import userEvent from "@testing-library/user-event";

import {
    VoiceBroadcastPlaybacksStore,
    VoiceBroadcastPreRecording,
    VoiceBroadcastPreRecordingPip,
    VoiceBroadcastRecordingsStore,
} from "../../../../src/voice-broadcast";
import { flushPromises, stubClient } from "../../../test-utils";
import { requestMediaPermissions } from "../../../../src/utils/media/requestMediaPermissions";
import MediaDeviceHandler, { MediaDeviceKindEnum } from "../../../../src/MediaDeviceHandler";
import dis from "../../../../src/dispatcher/dispatcher";
import { Action } from "../../../../src/dispatcher/actions";

jest.mock("../../../../src/dispatcher/dispatcher");
jest.mock("../../../../src/utils/media/requestMediaPermissions");

// mock RoomAvatar, because it is doing too much fancy stuff
jest.mock("../../../../src/components/views/avatars/RoomAvatar", () => ({
    __esModule: true,
    default: jest.fn().mockImplementation(({ room }) => {
        return <div data-testid="room-avatar">room avatar: {room.name}</div>;
    }),
}));

describe("VoiceBroadcastPreRecordingPip", () => {
    let renderResult: RenderResult;
    let preRecording: VoiceBroadcastPreRecording;
    let playbacksStore: VoiceBroadcastPlaybacksStore;
    let recordingsStore: VoiceBroadcastRecordingsStore;
    let client: MatrixClient;
    let room: Room;
    let sender: RoomMember;

    const itShouldShowTheBroadcastRoom = () => {
        it("should show the broadcast room", () => {
            expect(dis.dispatch).toHaveBeenCalledWith({
                action: Action.ViewRoom,
                room_id: room.roomId,
                metricsTrigger: undefined,
            });
        });
    };

    beforeEach(() => {
        client = stubClient();
        room = new Room("!room@example.com", client, client.getUserId() || "");
        sender = new RoomMember(room.roomId, client.getUserId() || "");
        playbacksStore = new VoiceBroadcastPlaybacksStore();
        recordingsStore = new VoiceBroadcastRecordingsStore();
        mocked(requestMediaPermissions).mockResolvedValue({
            getTracks: (): Array<MediaStreamTrack> => [],
        } as unknown as MediaStream);
        jest.spyOn(MediaDeviceHandler, "getDevices").mockResolvedValue({
            [MediaDeviceKindEnum.AudioInput]: [
                {
                    deviceId: "d1",
                    label: "Device 1",
                } as MediaDeviceInfo,
                {
                    deviceId: "d2",
                    label: "Device 2",
                } as MediaDeviceInfo,
            ],
            [MediaDeviceKindEnum.AudioOutput]: [],
            [MediaDeviceKindEnum.VideoInput]: [],
        });
        jest.spyOn(MediaDeviceHandler.instance, "setDevice").mockImplementation();
        preRecording = new VoiceBroadcastPreRecording(room, sender, client, playbacksStore, recordingsStore);
        jest.spyOn(preRecording, "start").mockResolvedValue();
        jest.spyOn(preRecording, "cancel");
    });

    afterAll(() => {
        jest.resetAllMocks();
    });

    describe("when rendered", () => {
        beforeEach(async () => {
            renderResult = render(<VoiceBroadcastPreRecordingPip voiceBroadcastPreRecording={preRecording} />);

            await act(async () => {
                flushPromises();
            });
        });

        it("should match the snapshot", () => {
            expect(renderResult.container).toMatchSnapshot();
        });

        it("starts once while initiation is pending and enables the button after resolution", async () => {
            let resolveStart: () => void;
            mocked(preRecording.start).mockReturnValue(new Promise<void>((resolve) => (resolveStart = resolve)));
            const button = screen.getByRole("button", { name: "Go live" });

            fireEvent.click(button);
            expect(button).toBeDisabled();
            fireEvent.click(button);
            fireEvent.keyDown(button, { key: "Enter", code: "Enter" });
            expect(preRecording.start).toHaveBeenCalledTimes(1);

            await act(async () => resolveStart());
            expect(button).not.toBeDisabled();
            await act(async () => {
                fireEvent.click(button);
            });
            expect(preRecording.start).toHaveBeenCalledTimes(2);
        });

        it("enables the button after a rejected initiation", async () => {
            let rejectStart: (reason: Error) => void;
            mocked(preRecording.start).mockReturnValue(new Promise<void>((_, reject) => (rejectStart = reject)));
            const button = screen.getByRole("button", { name: "Go live" });

            fireEvent.click(button);
            expect(button).toBeDisabled();
            await act(async () => rejectStart(new Error("start failed")));
            expect(button).not.toBeDisabled();
        });

        it("keeps a synchronous initiation disabled for the current tick", () => {
            jest.useFakeTimers();
            try {
                mocked(preRecording.start).mockImplementation(() => undefined as unknown as Promise<void>);
                const button = screen.getByRole("button", { name: "Go live" });

                fireEvent.click(button);
                fireEvent.click(button);
                expect(preRecording.start).toHaveBeenCalledTimes(1);
                expect(button).toBeDisabled();

                act(() => jest.runOnlyPendingTimers());
                expect(button).not.toBeDisabled();
            } finally {
                jest.useRealTimers();
            }
        });

        it("cancels once per close activation without changing a pending start", () => {
            mocked(preRecording.start).mockReturnValue(new Promise<void>(() => {}));
            const onDismiss = jest.fn();
            preRecording.on("dismiss", onDismiss);
            const button = screen.getByRole("button", { name: "Go live" });
            fireEvent.click(button);

            const close = renderResult.container.querySelector(".mx_VoiceBroadcastHeader > .mx_AccessibleButton:last-child");
            fireEvent.click(close);
            expect(preRecording.cancel).toHaveBeenCalledTimes(1);
            expect(onDismiss).toHaveBeenCalledTimes(1);
            expect(button).toBeDisabled();
        });

        it("opens only one device menu for repeated microphone activations", () => {
            const microphoneLine = screen.getByRole("button", { name: "Change input device" });
            act(() => {
                fireEvent.click(microphoneLine);
                fireEvent.click(microphoneLine);
            });
            expect(screen.getAllByText("Device 1")).toHaveLength(1);
            expect(screen.getAllByText("Device 2")).toHaveLength(1);
        });

        describe("and clicking the room name", () => {
            beforeEach(async () => {
                await userEvent.click(screen.getByText(room.name));
            });

            itShouldShowTheBroadcastRoom();
        });

        describe("and clicking the room avatar", () => {
            beforeEach(async () => {
                await userEvent.click(screen.getByText(`room avatar: ${room.name}`));
            });

            itShouldShowTheBroadcastRoom();
        });

        describe("and clicking the device label", () => {
            beforeEach(async () => {
                await act(async () => {
                    await userEvent.click(screen.getByText("Default Device"));
                });
            });

            it("should display the device selection", () => {
                expect(screen.queryAllByText("Default Device").length).toBe(2);
                expect(screen.queryByText("Device 1")).toBeInTheDocument();
                expect(screen.queryByText("Device 2")).toBeInTheDocument();
            });

            describe("and selecting a device", () => {
                beforeEach(async () => {
                    await act(async () => {
                        await userEvent.click(screen.getByText("Device 1"));
                    });
                });

                it("should set it as current device", () => {
                    expect(MediaDeviceHandler.instance.setDevice).toHaveBeenCalledWith(
                        "d1",
                        MediaDeviceKindEnum.AudioInput,
                    );
                });

                it("should not show the device selection", () => {
                    expect(screen.queryByText("Default Device")).not.toBeInTheDocument();
                    // expected to be one in the document, displayed in the pip directly
                    expect(screen.queryByText("Device 1")).toBeInTheDocument();
                    expect(screen.queryByText("Device 2")).not.toBeInTheDocument();
                });

                it("can reopen the menu and update the microphone label again", async () => {
                    const microphoneLine = screen.getByRole("button", { name: "Change input device" });
                    expect(microphoneLine).toHaveTextContent("Device 1");

                    await userEvent.click(microphoneLine);
                    await userEvent.click(screen.getByText("Device 2"));

                    expect(MediaDeviceHandler.instance.setDevice).toHaveBeenLastCalledWith(
                        "d2",
                        MediaDeviceKindEnum.AudioInput,
                    );
                    expect(microphoneLine).toHaveTextContent("Device 2");
                    expect(screen.queryByText("Device 1")).not.toBeInTheDocument();
                });
            });
        });
    });
});

